package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LocaleUtils_isAvailableLocale_TriageGen3Test {

    @Test
    public void testIsAvailableLocale_WithExistingLocale() {
        // Get a known available locale from the set to ensure true result
        Set<Locale> availableSet = LocaleUtils.availableLocaleSet();
        if (!availableSet.isEmpty()) {
            Locale existingLocale = availableSet.iterator().next();
            assertTrue("Expected locale should be available", LocaleUtils.isAvailableLocale(existingLocale));
        }
    }

    @Test
    public void testIsAvailableLocale_WithNonExistingLocale() {
        // Use a locale that is highly unlikely to be in the available set
        Locale nonExistingLocale = Locale.forLanguageTag("xx-YY");
        assertFalse("Expected locale should not be available", LocaleUtils.isAvailableLocale(nonExistingLocale));
    }

    @Test
    public void testIsAvailableLocale_WithNull() {
        // Testing null behavior. Depending on implementation of cAvailableLocaleSet.contains(null)
        // Usually HashSet.contains(null) returns false if null is not in set.
        assertFalse("Expected null to return false", LocaleUtils.isAvailableLocale(null));
    }

    @Test
    public void testIsAvailableLocale_WithCommonLocales() {
        // Test standard constants
        // We check if they are available; if they aren't in the specific set, the test still passes the logic check
        Locale us = Locale.US;
        boolean result = LocaleUtils.isAvailableLocale(us);

        // We don't assert true/false here because the available set is environment/library dependent,
        // but we ensure the method executes without exception for valid Locale objects.
    }
}
